// ============================================================================
// 1. الأنواع وهياكل البيانات (Types & Firestore Schema)
// ============================================================================

export type GameId =
  | 'surah-keys'
  | 'vocab-memory'
  | 'quran-detective'
  | 'order-scenes'
  | 'verse-to-lesson'
  | 'sixty-seconds';

export type AttemptStatus = 'in_progress' | 'completed';

export interface OptionWithId {
  optionId: string;
  text: string;
}

export interface AnswerRecord {
  questionId: string;
  questionText: string;
  originalOptionIds?: string[];
  originalCorrectOptionId?: string;
  displayedOptionIds?: string[];
  displayedOptionsText?: string[];
  selectedOptionId?: string;
  correctOptionId?: string;
  displayedCorrectPosition?: 'A' | 'B' | 'C' | 'D' | string;
  displayedSelectedPosition?: 'A' | 'B' | 'C' | 'D' | string;
  selectedAnswer: string;
  correctAnswer: string;
  isCorrect: boolean;
  explanation: string;
  answeredAt: string;
  timeSpentSeconds: number;
}

export interface AttemptRecord {
  attemptId: string;
  studentUid: string;
  studentName: string;
  className: string;
  gameId: GameId;
  gameName: string;
  answers: AnswerRecord[];
  score: number;
  maxScore: number;
  percentage: number;
  startedAt: string;
  submittedAt: string;
  duration: number;
  status: AttemptStatus;
  syncedToCloud: boolean;
}

export interface StudentSession {
  studentUid: string;
  studentName: string;
  className: string;
  sessionId: string;
  startedAt: string;
}

export interface VerseItem {
  ayahNumber: number;
  text: string;
  topic: string;
  tafsirSummary: string;
  lessons: string[];
}

export interface VocabItem {
  id: string;
  word: string;
  ayahNumber: number;
  meaning: string;
  contextHint: string;
}

export interface GameMetadata {
  id: GameId;
  title: string;
  subtitle: string;
  description: string;
  iconType: GameId;
  maxScore: number;
  questionsCount: number;
  estimatedMinutes: number;
  badgeTitle: string;
}

export type ChallengeType =
  | 'اختيار الإجابة الصحيحة'
  | 'إكمال المعنى'
  | 'اختيار التفسير المناسب'
  | 'اكتشاف المعلومة الصحيحة'
  | 'ربط الدليل بالنتيجة';

export interface GameQuestion {
  id: string;
  stationId?: number;
  stationName?: string;
  challengeType?: ChallengeType;
  questionText: string;
  ayahReference: string;
  options: string[];
  correctAnswer: string;
  explanation: string;
  hint?: string;
}

export interface AdventureStation {
  stationNumber: number;
  id: string;
  title: string;
  ayahRange: string;
  iconKey: 'eye' | 'landmarks' | 'shield' | 'promise' | 'scales' | 'light';
  introTitle: string;
  storyIntro: string;
  verseSnippet: string;
  keyRewardTitle: string;
  challengeTitle: string;
}

export type MemoryDifficulty = 6 | 10 | 15;

export interface MemoryCardTile {
  tileId: string;
  pairId: string;
  kind: 'word' | 'meaning';
  displayText: string;
  wordText: string;
  meaningText: string;
  ayahNumber: number;
  contextHint: string;
}

export interface DetectiveCaseItem {
  id: string;
  caseNumber: number;
  statement: string;
  ayahNumber: number;
  verseEvidence: string;
  isStatementTrue: boolean;
  correctionOptions?: string[];
  correctCorrection?: string;
  explanation: string;
}

export interface OrderSceneCardItem {
  id: string;
  correctPosition: number;
  cardLabel: string;
  sceneText: string;
  ayahRange: string;
  verseExcerpt: string;
  connectionExplanation: string;
}

export type ScenarioSkillCategory =
  | 'فهم المعاني'
  | 'الربط والاستنتاج'
  | 'استخلاص الدروس';

export interface ScenarioDecisionItem {
  id: string;
  scenarioNumber: number;
  levelNumber: 1 | 2 | 3;
  levelTitle: string;
  skillCategory: ScenarioSkillCategory;
  title: string;
  storyText: string;
  ayahReference: string;
  verseText: string;
  questionText: string;
  options: string[];
  correctAnswer: string;
  educationalExplanation: string;
}

export type SixtyQuizCategory =
  | 'معاني المفردات'
  | 'فهم مضمون الآيات'
  | 'الترتيب الموضوعي'
  | 'الدروس المستفادة'
  | 'الاختيار بين المعاني المتقاربة'
  | 'اكتشاف المعلومة غير الصحيحة';

export interface SixtySecondQuestionItem {
  id: string;
  category: SixtyQuizCategory;
  difficulty: 'سهل' | 'متوسط' | 'متقدم';
  ayahReference: string;
  questionText: string;
  options: string[];
  correctAnswer: string;
  explanation: string;
}

