// ============================================================================
// محرك التوزيع العشوائي الذكي ومنع الأنماط المتوقعة (Fisher-Yates + Balanced A/B/C/D Quota)
// ونظام المعرفات الدائمة للإجابات (Permanent Option IDs)
// ============================================================================

export const POSITION_LABELS: ('A' | 'B' | 'C' | 'D')[] = ['A', 'B', 'C', 'D'];
export const ARABIC_POS_LABELS: string[] = ['أ (A)', 'ب (B)', 'ج (C)', 'د (D)'];

export interface PreparedQuestionMeta {
  questionId: string;
  originalOptionIds: string[];
  originalCorrectOptionId: string;
  displayedOptions: OptionWithId[];
  displayedOptionIds: string[];
  displayedOptionsText: string[];
  correctOptionId: string;
  displayedCorrectPosition: 'A' | 'B' | 'C' | 'D';
}

export function fisherYatesShuffle<T>(items: T[]): T[] {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const temp = copy[i];
    copy[i] = copy[j];
    copy[j] = temp;
  }
  return copy;
}

/**
 * يولّد سلسلة مواقع متوازنة وعشوائية للإجابات الصحيحة عبر (A, B, C, D)
 * بحيث تتوزع بالتساوي (مثلاً 5 في كل موقع لـ 20 سؤالاً) مع خلط كل مجموعة
 * ومنع تكرار نفس الموقع لأكثر من سؤالين متتاليين، ومنع التسلسلات النمطية (A,B,C,D,A,B,C,D).
 */
export function generateBalancedTargetPositions(totalQuestions: number): number[] {
  if (totalQuestions <= 0) return [];
  const targets: number[] = [];
  const fullBlocks = Math.floor(totalQuestions / 4);
  const remainder = totalQuestions % 4;

  for (let b = 0; b < fullBlocks; b++) {
    let block = fisherYatesShuffle([0, 1, 2, 3]);
    for (let retry = 0; retry < 12; retry++) {
      const candidate = [...targets, ...block];
      const last8 = candidate.slice(-8).join("");
      const hasCyclic =
        last8.includes("01230123") ||
        last8.includes("12301230") ||
        last8.includes("23012301") ||
        last8.includes("30123012") ||
        last8.includes("32103210") ||
        last8.includes("21032103") ||
        last8.includes("10321032") ||
        last8.includes("03210321");
      const hasTripleStreak =
        targets.length >= 2 &&
        targets[targets.length - 1] === targets[targets.length - 2] &&
        block[0] === targets[targets.length - 1];
      if (!hasCyclic && !hasTripleStreak) break;
      block = fisherYatesShuffle([0, 1, 2, 3]);
    }
    targets.push(...block);
  }

  if (remainder > 0) {
    const remPool = fisherYatesShuffle([0, 1, 2, 3]).slice(0, remainder);
    if (targets.length >= 2) {
      const last1 = targets[targets.length - 1];
      const last2 = targets[targets.length - 2];
      if (last1 === last2 && remPool[0] === last1 && remPool.length > 1) {
        const tmp = remPool[0];
        remPool[0] = remPool[1];
        remPool[1] = tmp;
      }
    }
    targets.push(...remPool);
  }

  return targets;
}

/**
 * يبني الاختيارات الأربعة بمعرفاتها الدائمة (Permanent Option IDs) ويضع الإجابة الصحيحة
 * في الموقع المستهدف المتوازن مع خلط بقية المشتتات بـ Fisher-Yates.
 */
export function buildRandomizedOptionsForQuestion(
  questionId: string,
  rawOptions: string[],
  correctAnswerText: string,
  targetCorrectIndex: number
): PreparedQuestionMeta {
  // ربط كل خيار بمعرف دائم فريد لا يتغير بالخلط
  const taggedOptions: OptionWithId[] = rawOptions.map((txt, idx) => ({
    optionId: `${questionId}_opt_${idx + 1}`,
    text: txt
  }));

  const originalOptionIds = taggedOptions.map((o) => o.optionId);
  const correctObj =
    taggedOptions.find((o) => o.text === correctAnswerText) || taggedOptions[0];
  const distractors = fisherYatesShuffle(
    taggedOptions.filter((o) => o.optionId !== correctObj.optionId)
  );

  const safeTargetIndex = Math.max(0, Math.min(taggedOptions.length - 1, targetCorrectIndex));
  const displayedOptions: OptionWithId[] = [];
  let dIdx = 0;

  for (let pos = 0; pos < taggedOptions.length; pos++) {
    if (pos === safeTargetIndex) {
      displayedOptions.push(correctObj);
    } else if (dIdx < distractors.length) {
      displayedOptions.push(distractors[dIdx++]);
    }
  }

  return {
    questionId,
    originalOptionIds,
    originalCorrectOptionId: correctObj.optionId,
    displayedOptions,
    displayedOptionIds: displayedOptions.map((o) => o.optionId),
    displayedOptionsText: displayedOptions.map((o) => o.text),
    correctOptionId: correctObj.optionId,
    displayedCorrectPosition: POSITION_LABELS[safeTargetIndex] || 'A'
  };
}

/**
 * التحقق الآمن من صحة إجابة الطالب بالاعتماد الحصري على المعرف الدائم (Permanent Option ID)
 * وليس على موقع الخيار المعروض (A, B, C, D).
 */
export function validateAnswerByPermanentOptionId(
  meta: PreparedQuestionMeta | undefined,
  chosenText: string,
  fallbackCorrectText: string
): {
  isCorrect: boolean;
  selectedOptionId: string;
  correctOptionId: string;
  displayedSelectedPosition: 'A' | 'B' | 'C' | 'D';
  displayedCorrectPosition: 'A' | 'B' | 'C' | 'D';
  originalOptionIds: string[];
  displayedOptionIds: string[];
  displayedOptionsText: string[];
} {
  if (!meta) {
    const isRight = chosenText === fallbackCorrectText;
    return {
      isCorrect: isRight,
      selectedOptionId: isRight ? 'opt_1' : 'opt_2',
      correctOptionId: 'opt_1',
      displayedSelectedPosition: 'A',
      displayedCorrectPosition: 'A',
      originalOptionIds: ['opt_1', 'opt_2', 'opt_3', 'opt_4'],
      displayedOptionIds: ['opt_1', 'opt_2', 'opt_3', 'opt_4'],
      displayedOptionsText: [fallbackCorrectText]
    };
  }

  const chosenIdx = meta.displayedOptions.findIndex((o) => o.text === chosenText);
  const chosenObj =
    chosenIdx !== -1
      ? meta.displayedOptions[chosenIdx]
      : { optionId: `${meta.questionId}_opt_unanswered`, text: chosenText };
  const correctIdx = meta.displayedOptions.findIndex(
    (o) => o.optionId === meta.correctOptionId
  );

  // المقارنة الحاسمة عبر المعرف الدائم فقط (selectedOptionId === correctOptionId)
  const isCorrect = chosenObj.optionId === meta.correctOptionId;

  return {
    isCorrect,
    selectedOptionId: chosenObj.optionId,
    correctOptionId: meta.correctOptionId,
    displayedSelectedPosition:
      chosenIdx >= 0 && chosenIdx < 4 ? POSITION_LABELS[chosenIdx] : 'A',
    displayedCorrectPosition:
      correctIdx >= 0 && correctIdx < 4
        ? POSITION_LABELS[correctIdx]
        : meta.displayedCorrectPosition,
    originalOptionIds: meta.originalOptionIds,
    displayedOptionIds: meta.displayedOptionIds,
    displayedOptionsText: meta.displayedOptionsText
  };
}

